'use server'

import { revalidatePath } from 'next/cache'
import { cookies } from 'next/headers'

const NOTIFICATION_COOKIE = 'notifications-enabled'

export async function getNotificationPreference(): Promise<boolean> {
  const store = await cookies()
  const value = store.get(NOTIFICATION_COOKIE)?.value
  return value !== 'false'
}

export async function toggleNotificationPreference(): Promise<void> {
  const store = await cookies()
  const current = store.get(NOTIFICATION_COOKIE)?.value
  const nextValue = current === 'false' ? 'true' : 'false'

  store.set(NOTIFICATION_COOKIE, nextValue, {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
  })

  revalidatePath('/')
}

