import {
  getNotificationPreference,
  toggleNotificationPreference,
} from './actions'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Notifications: {notificationsEnabled ? 'On' : 'Off'}
        </button>
      </form>
      <p>
        Click the button to toggle. The page refreshes server-side to show the
        updated preference.
      </p>
    </main>
  )
}

